result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_hull.py", "content": "from hypothesis import given, settings, strategies as st

from hull import convex_hull

lattice_points = st.lists(
    st.tuples(st.integers(-50, 50), st.integers(-50, 50)), max_size=60
)


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def point_in_convex_polygon(p, poly):
    """Exact check that p is inside or on the boundary of CCW polygon poly."""
    n = len(poly)
    for i in range(n):
        if cross(poly[i], poly[(i + 1) % n], p) < 0:
            return False
    return True


# ---------- hand cases ----------


def test_square_with_center():
    pts = [(0, 0), (2, 0), (2, 2), (0, 2), (1, 1)]
    assert convex_hull(pts) == [(0, 0), (2, 0), (2, 2), (0, 2)]


def test_all_collinear():
    pts = [(0, 0), (1, 1), (2, 2), (3, 3), (-1, -1)]
    assert convex_hull(pts) == [(-1, -1), (3, 3)]


def test_duplicates():
    pts = [(5, 5), (5, 5), (5, 5)]
    assert convex_hull(pts) == [(5, 5)]


def test_triangle():
    pts = [(0, 0), (4, 0), (2, 3)]
    assert convex_hull(pts) == [(0, 0), (4, 0), (2, 3)]


def test_two_distinct_points():
    pts = [(3, 7), (1, 2), (3, 7)]
    assert convex_hull(pts) == [(1, 2), (3, 7)]


def test_single_point():
    assert convex_hull([(9, -9)]) == [(9, -9)]


def test_empty():
    assert convex_hull([]) == []


# ---------- properties ----------


@given(lattice_points)
def test_idempotent(points):
    h1 = convex_hull(points)
    h2 = convex_hull(h1)
    assert h1 == h2


@given(lattice_points)
def test_all_points_inside_or_on_hull(points):
    hull = convex_hull(points)
    if len(hull) < 3:
        # Degenerate: segment or point — just check containment trivially holds
        assert all(p in points or True for p in hull)
        return
    for p in points:
        assert point_in_convex_polygon(p, hull)


@given(lattice_points)
def test_output_is_convex(points):
    hull = convex_hull(points)
    if len(hull) < 3:
        return
    n = len(hull)
    for i in range(n):
        c = cross(hull[i], hull[(i + 1) % n], hull[(i + 2) % n])
        assert c > 0, f"non-convex or collinear at {i}: cross={c}, hull={hull}"
